<div class="portal-page">
  <?php if($flash): ?><div class="portal-alert <?= h($flash['type']) ?>" role="status"><?= h($flash['message']) ?></div><?php endif; ?>
  <div class="portal-section-heading"><div><span class="eyebrow">SEGUIMIENTO</span><h2>Mis solicitudes</h2><p>Las solicitudes se generan cuando envías un diseño para revisión. Aquí puedes consultar su estado.</p></div><a class="portal-outline-button" href="<?= h(url('disenador')) ?>">＋ Preparar diseño</a></div>
  <?php if(!$solicitudes): ?><div class="portal-empty"><span>◇</span><h3>Todavía no enviaste solicitudes</h3><p>Cuando termines de personalizar una prenda, selecciona “Enviar solicitud” para compartir tu propuesta.</p><a class="portal-primary" href="<?= h(url('disenador')) ?>">Diseñar una prenda</a></div>
  <?php else: ?><div class="request-list"><?php foreach($solicitudes as $s): $pill=in_array($s['estado'],['Aprobada','Finalizada'],true)?'approved':($s['estado']==='Rechazada'?'rejected':($s['estado']==='Pendiente'||$s['estado']==='En proceso'?'pending':'neutral')); ?><article class="request-card"><div class="request-card-symbol">◇</div><div class="request-card-main"><div class="request-title-row"><h3>Solicitud #<?= (int)$s['id'] ?> · <?= h($s['prenda']) ?></h3><span class="status-pill <?= $pill ?>"><?= h($s['estado']) ?></span></div><p><?= h($s['talla']) ?> · <?= h($s['color']) ?> · <?= h($s['tela']) ?></p><?php if($s['descripcion']): ?><small><?= h($s['descripcion']) ?></small><?php endif; ?><div class="request-dates"><span>Enviada: <?= h(date('d/m/Y H:i',strtotime($s['creado_en']))) ?></span><span>Última actualización: <?= h(date('d/m/Y H:i',strtotime($s['actualizado_en']))) ?></span></div></div></article><?php endforeach; ?></div><?php endif; ?>
